  function ingIcon(item){if(!item.icon)return `<span class="emoji" aria-hidden="true">${item.emoji||''}</span>`;const [n,x,y,w,h]=item.icon,k=`ic-${item.id}`;return `<svg class="ing-icon" viewBox="${x} ${y} ${w} ${h}" aria-hidden="true"><clipPath id="${k}"><rect x="${x}" y="${y}" width="${w}" height="${h}"/></clipPath><image href="${INGREDIENT_SHEETS[n]}" width="1145" height="1374" clip-path="url(#${k})"/></svg>`;}
  function toolIcon(t){const [x,y,w,h]=t.sprite,k=`tl-${t.id}`;return `<svg class="tool-icon" viewBox="${x} ${y} ${w} ${h}" aria-hidden="true"><clipPath id="${k}"><rect x="${x}" y="${y}" width="${w}" height="${h}"/></clipPath><image href="assets/tools.webp" width="1536" height="1024" clip-path="url(#${k})"/></svg>`;}
