  function langSwitch(){return `<div class="lang-switch" role="group" aria-label="${t('언어')}">${[['ja','日本語'],['ko','한국어']].map(([id,n])=>`<button class="lang-option ${I.lang===id?'active':''}" data-action="lang" data-id="${id}" lang="${id}" aria-pressed="${I.lang===id}">${n}</button>`).join('')}</div>`;}
