  function blogLink(q,dot){const ja=I.lang==='ja';return `<a class="external-link" href="${ja?`https://cookpad.com/jp/search/${q}`:`https://search.naver.com/search.naver?where=blog&query=${q}`}" target="_blank" rel="noopener noreferrer">${dot?`<span class="nv-dot" aria-hidden="true">${ja?'C':'N'}</span>`:''}${dot?(ja?t('쿡패드'):t('네이버 블로그')):(ja?t('쿡패드에서 검색하기'):t('네이버 블로그에서 검색하기'))} ${icon('external')}</a>`;}
  function nav(){return page==='welcome'||onboarding||!state.onboardingComplete?'':`<nav class="bottom-nav" aria-label="${t('주요 메뉴')}">${[['home','내 집','home'],['fridge','냉장고','fridge'],['recipes','요리책','book'],['kitchen','내 주방','pot']].map(([id,label,ic])=>`<button class="nav-button ${page===id||id==='recipes'&&page==='detail'?'active':''}" data-action="nav" data-page="${id}" ${page===id||id==='recipes'&&page==='detail'?'aria-current="page"':''}>${icon(ic)}<span>${t(label)}</span></button>`).join('')}</nav>`;}
  function banner(){return !storageAvailable?`<div class="memory-banner" role="status">${icon('info')}${t('이 브라우저에서는 저장할 수 없어 이번 방문 동안만 유지돼요. 새로고침하면 초기화돼요.')}</div>`:recoveryNotice?`<div class="memory-banner" role="status">${t('저장된 정보를 읽지 못해 처음 상태로 복구했어요. 다시 설정해주세요.')}</div>`:'';}
  // 찜: 하트는 카드 버튼 밖(겹쳐 놓은 별도 버튼)이라 카드를 눌러도 찜이 바뀌지 않는다.
  const isFav=id=>M.favoritesOf(state).includes(id);
  const heartSvg='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20.5s-8.5-5.2-8.5-11A4.8 4.8 0 0 1 12 6.7a4.8 4.8 0 0 1 8.5 2.8c0 5.8-8.5 11-8.5 11Z"/></svg>';
  function favButton(recipe,extra=''){const on=isFav(recipe.id);return `<button class="fav-button ${on?'on':''} ${extra}" data-action="favorite" data-id="${recipe.id}" aria-pressed="${on}" aria-label="${t(on?'{name} 즐겨찾기 해제':'{name} 즐겨찾기',{name:recipe.name})}">${heartSvg}</button>`;}
  function cardWrap(recipe,horizontal,card){return `<div class="card-wrap ${horizontal?'horizontal':''}">${card}${favButton(recipe)}</div>`;}
  // 추천 카드: 고른 친구가 요리를 소개한다. 같은 요리·친구면 늘 같은 대사가 나오도록 id로 고른다.
  const LEVEL_WORD={easy:'쉬운',medium:'적당한',hard:'조금 어려운'};
  const pickOf=(list,key)=>{let h=0;for(const ch of key)h=(h*31+ch.charCodeAt(0))>>>0;return list[h%list.length];};
  const withJosa=(word,batchim,plain)=>{const code=word.charCodeAt(word.length-1)-0xac00;return word+(code>=0&&code<11172&&code%28?batchim:plain);};
  const cookWith=c=>I.lang==='ko'?`${withJosa(c.name,'이랑','랑')} 요리하기`:t('{name}랑 요리하기',{name:c.name});
  function friendLine(c,r){const key=r.id+c.id;return {quote:pickOf(c.pick.quotes,key),sub:pickOf(c.pick.subs,key+'+').replace(/\{요리\}/g,r.name).replace(/\{시간\}/g,r.minutes).replace(/\{난이도\}/g,t(LEVEL_WORD[r.difficulty]))};}
  // 얼굴만 있는 그림(배경 없음). 영역 밖이 비치지 않게 잘라서 그린다.
