  function friendPick(r,{kicker,cta,extra='',heading='h3',head=true}){const c=D.characters.find(c=>c.id===state.selectedCharacter)||D.characters[1],{quote,sub}=friendLine(c,r);return `<article class="friend-pick">${head?`<div class="fp-head"><span class="fp-kicker">${kicker}</span><span class="fp-chip">${t('{name} 선택 중',{name:c.name})}</span></div>`:''}<div class="fp-talk"><div class="fp-face">${faceArt(c)}</div><div class="fp-words"><p class="fp-quote">“${quote}”</p><p class="fp-sub">${sub}</p></div></div><div class="fp-art">${foodArt(r)}${favButton(r)}</div><div class="fp-title"><${heading} class="fp-name" ${heading==='h1'?'tabindex="-1"':''}>${r.name}</${heading}><span class="fp-meta">${t('약 {n}분',{n:r.minutes})} · ${D.difficultyNames[r.difficulty]}</span></div>${extra}${cta}</article>`;}
  function recipeCard(recipe,horizontal=false){const s=recipe.status||M.recipeStatus(recipe,state);const missing=[...s.missingIngredients.map(id=>nameOf(id)),...s.missingCondiments.map(id=>nameOf(id,'condiments'))];return cardWrap(recipe,horizontal,`<button class="recipe-card ${horizontal?'horizontal':''}" data-action="recipe" data-id="${recipe.id}" aria-label="${recipe.name}, ${D.difficultyNames[recipe.difficulty]}, ${t('{n}분',{n:recipe.minutes})}${!s.hasTools?', '+t('도구 필요'):missing.length?', '+t('부족: {list}',{list:missing.join(', ')}):', '+t('바로 만들 수 있음')} — ${t('예시 상세 보기')}">${foodArt(recipe)}<div class="recipe-copy"><h3>${recipe.name}</h3>${recipe.mealType?`<span class="meal-type">${recipe.mealType}</span>`:''}<div class="recipe-meta"><span class="badge ${recipe.difficulty}">${D.difficultyNames[recipe.difficulty]}</span><span>${icon('clock')}${t('{n}분',{n:recipe.minutes})}</span><span>${icon('pan')}${names(recipe.tools,'tools')||t('가열 없이')}</span></div>${!s.hasTools?`<span class="missing-badge">${t('필요 도구: {list}',{list:names(recipe.tools.filter(id=>!state.tools.includes(id)),'tools')})}</span>`:''}${missing.length?`<span class="missing-badge">${t('부족: {list}',{list:missing.join(', ')})}</span>`:''}</div>${horizontal?`<span class="card-arrow">${icon('chevron')}</span>`:''}</button>`);}
